export default async function handler(req, res) {
  const url = new URL(req.url, 'http://localhost');
  const p = url.searchParams.get('p');
  const m = p ? p.match(/^([^/]+)\/([^/]+)\/(.*)$/) : null;
  if (!m) { res.statusCode = 404; res.end(JSON.stringify({ error: 'Not found', p, url: req.url })); return; }
  const ex = m[1] + '/' + m[2];
  const handlerId = m[3];
  const h = handlers[ex];
  if (!h) { res.statusCode = 404; res.end(JSON.stringify({ error: 'Not found', ex, keys: Object.keys(handlers).slice(0,3) })); return; }
  url.pathname = `/api/astra/${handlerId}`;
  url.search = '';
  req.url = url.toString();
  return h(req, res);
}
